import re
import json
import sys

def parse_script(text: str):
    nodes = []
    edges = []

    lines = text.splitlines()
    current_node = None

    node_dict = {}

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Node header
        node_match = re.match(r'^\[(.*?)\]$', line)
        if node_match:
            node_id = node_match.group(1).strip()
            current_node = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "line" # Default
            }
            nodes.append(current_node)
            node_dict[node_id] = current_node
            continue

        if current_node:
            # Line type: Speaker: Text -> Target
            line_match = re.match(r'^(.*?):\s*(.*?)\s*->\s*(.*)$', line)
            if line_match:
                speaker = line_match.group(1).strip()
                content = line_match.group(2).strip()
                target = line_match.group(3).strip()

                current_node["speaker"] = speaker
                current_node["text"] = content
                current_node["type"] = "line"

                edges.append({
                    "from": current_node["id"],
                    "to": target,
                    "text": ""
                })
                continue

            # Choice type: 1. Text -> Target
            choice_match = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', line)
            if choice_match:
                content = choice_match.group(1).strip()
                target = choice_match.group(2).strip()

                current_node["type"] = "choice"

                edges.append({
                    "from": current_node["id"],
                    "to": target,
                    "text": content
                })
                continue

    # Validation and graph cleanup
    existing_node_ids = {node["id"] for node in nodes}
    all_targets = set(edge["to"] for edge in edges)

    for target in all_targets:
        if target not in existing_node_ids:
            nodes.append({
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            existing_node_ids.add(target)

    # Reachability check from the first node
    if nodes:
        # Sort nodes by appearance in script to determine first node
        # But they are already in order of appearance
        first_node_id = nodes[0]["id"]
        reachable = {first_node_id}
        queue = [first_node_id]

        adj = {}
        for edge in edges:
            if edge["from"] not in adj:
                adj[edge["from"]] = []
            adj[edge["from"]].append(edge["to"])

        while queue:
            curr = queue.pop(0)
            for neighbor in adj.get(curr, []):
                if neighbor not in reachable:
                    reachable.add(neighbor)
                    queue.append(neighbor)

        # Only keep reachable nodes and edges
        nodes = [n for n in nodes if n["id"] in reachable]
        edges = [e for e in edges if e["from"] in reachable and e["to"] in reachable]

    return {"nodes": nodes, "edges": edges}

def generate_dot(graph):
    dot = "digraph Dialogue {\n"
    dot += "  node [shape=box];\n"

    for node in graph["nodes"]:
        # Sanitize for DOT
        label_parts = [node['id'], f"({node['type']})"]
        if node['speaker']:
            label_parts.append(f"{node['speaker']}: {node['text']}")
        elif node['text']:
            label_parts.append(node['text'])

        label = "\\n".join(label_parts).replace('"', '\\"')
        dot += f'  "{node["id"]}" [label="{label}"];\n'

    for edge in graph["edges"]:
        label = edge["text"].replace('"', '\\"')
        dot += f'  "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];\n'

    dot += "}\n"
    return dot

if __name__ == "__main__":
    try:
        with open("/app/script.txt", "r") as f:
            content = f.read()

        graph = parse_script(content)

        with open("/app/dialogue.json", "w") as f:
            json.dump(graph, f, indent=2)

        dot_content = generate_dot(graph)
        with open("/app/dialogue.dot", "w") as f:
            f.write(dot_content)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

