                "type": "line" 
            }
            nodes.append(current_node)
            node_dict[node_id] = current_node
            continue

        if current_node:
            # Line type: Speaker: Text -> Target
            line_match = re.search(r'^(.*?):\s*(.*?)\s*->\s*(.*)$', line)
            if line_match:
                speaker = line_match.group(1).strip()
                content = line_match.group(2).strip()
                target = line_match.group(3).strip()

                current_node["speaker"] = speaker
                current_node["text"] = content
                current_node["type"] = "line"

                edges.append({
                    "from": current_node["id"],
