                    "text": ""
                })
                continue

            # Choice type: 1. Text -> Target
            choice_match = re.search(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', line)
            if choice_match:
                content = choice_match.group(1).strip()
                target = choice_match.group(2).strip()

                current_node["type"] = "choice"

                edges.append({
                    "from": current_node["id"],
                    "to": target,
                    "text": content
                })
                continue

